for song_id in target_song_ids:
    reviews = apis.spotify.show_song_reviews(song_id=song_id)
    if reviews:
        existing_reviews[song_id] = max(review['rating'] for review in reviews)
print(existing_reviews)

rating_results = []
for song_id in target_song_ids:
    if song_id in existing_reviews and existing_reviews[song_id] >= 1:
        if existing_reviews[song_id] > 1:
            delete_result = apis.spotify.delete_song_review(song_id=song_id, access_token=spotify_access_token)
            rating_results.append({'song_id': song_id, 'action': 'delete', 'result': delete_result})
        else:
            rating_results.append({'song_id': song_id, 'action': 'no-op', 'existing_rating': existing_reviews[song_id]})
    else:
        review_result = apis.spotify.review_song(song_id=song_id, rating=1, access_token=spotify_access_token)
        rating_results.append({'song_id': song_id, 'action': 'create', 'result': review_result})
print(rating_results)

